        self._items.append((value, minimum))

    def pop(self):
        return self._items.pop()[0]

    def top(self):
        return self._items[-1][0]

    def get_min(self):
        if not self._items:
            raise ValueError("empty stack has no minimum")
        return self._items[-1][1]

    def __len__(self):
